create function pg_temp.extend(days integer,reason text,revision integer) returns integer language sql as $$select public.extend_employee_document_deadline_service('15200000-0000-4000-8000-000000000001','25200000-0000-4000-8000-000000000001','65200000-0000-4000-8000-000000000001',revision,days,reason)$$;
select throws_ok($$select pg_temp.extend(3,'',1)$$,'22023',null,'deadline extension requires a reason');
select lives_ok($$select pg_temp.extend(3,'Issuer delayed the certificate',1)$$,'scoped reviewer extends before suspension');
select is((select deadline_at from public.employee_onboarding_requirements where id='65200000-0000-4000-8000-000000000001'),now()+interval '10 days','extension adds explicit days to the existing deadline');
select is((select lifecycle_settings->>'period_days' from public.employee_onboarding_requirements where id='65200000-0000-4000-8000-000000000001'),'7','extension preserves configured full correction period');
select throws_ok($$select pg_temp.extend(3,'Duplicate',1)$$,'PT409',null,'stale extension cannot double-extend');
select throws_ok($$select public.extend_employee_document_deadline_service('15200000-0000-4000-8000-000000000002','25200000-0000-4000-8000-000000000001','65200000-0000-4000-8000-000000000001',2,3,'Self')$$,'42501',null,'employee cannot extend their own deadline');
update public.employee_onboarding_requirements set deadline_at=now()-interval '1 second' where id='65200000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.extend(3,'Too late',2)$$,'22023',null,'elapsed blocker cannot be extended to reopen access');
select is((select count(*)::integer from public.onboarding_events where action='document.deadline_extended'),1,'one audit event records the valid deadline decision');
select * from finish();rollback;
